    public long? DurationMs { get; init; }

    [JsonPropertyName("usage")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public ScriptUsage? Usage { get; init; }

    /// <summary>The answer before anything read it. Only while `llm.captureWrites` is on</summary>
    [JsonPropertyName("raw")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Raw { get; init; }

    /// <summary>What the writer sent. Only while `llm.captureWrites` is on</summary>
    [JsonPropertyName("prompt")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public List<ScriptPromptMessage>? Prompt { get; init; }

    /// <summary>What the operator thought of it. ABSENT means nobody has said, which `neutral` does not</summary>
    [JsonPropertyName("rating")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public ScriptRating? Rating { get; init; }
}

/// <summary>One attempt to write something the station would say, including the ones that came to nothing</summary>
public sealed record ScriptAttemptInput
{
    [JsonPropertyName("id")]
    public required string Id { get; init; }

    [JsonPropertyName("at")]
    public required DateTimeOffset At { get; init; }

    /// <summary>What sort of break it was for: `talkbreak`, `welcome`, `news`</summary>
    [JsonPropertyName("kind")]
    public required string Kind { get; init; }

    /// <summary>The binding that produced or declined it</summary>
    [JsonPropertyName("writer")]
    public required string Writer { get; init; }

    [JsonPropertyName("outcome")]
    public required ScriptOutcome Outcome { get; init; }

    /// <summary>Who was presenting, as the persona's own key. Absent means nobody was, which is an ordinary state. Stamped on every attempt including the declined ones, so a character whose model breaks are all being refused is visible rather than hidden behind the floor</summary>
    [JsonPropertyName("personaKey")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? PersonaKey { get; init; }

    [JsonPropertyName("label")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Label { get; init; }

    /// <summary>The words. Absent for an attempt that produced none</summary>
    [JsonPropertyName("script")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Script { get; init; }

    /// <summary>The model that said it, for a writer that used one</summary>
    [JsonPropertyName("model")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Model { get; init; }

    /// <summary>What the line was rendered from, for a writer working from something an operator can edit</summary>
    [JsonPropertyName("source")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Source { get; init; }

    /// <summary>Why, for anything that is not `written`</summary>
    [JsonPropertyName("reason")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Reason { get; init; }

    /// <summary>The segment this was for, while it is still known. The row outlives it</summary>
    [JsonPropertyName("segmentId")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? SegmentId { get; init; }

    [JsonPropertyName("previous")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public ScriptNeighbour? Previous { get; init; }

    [JsonPropertyName("next")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public ScriptNeighbour? Next { get; init; }

    /// <summary>How long the attempt took</summary>
    [JsonPropertyName("durationMs")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public long? DurationMs { get; init; }

    [JsonPropertyName("usage")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public ScriptUsage? Usage { get; init; }

    /// <summary>The answer before anything read it. Only while `llm.captureWrites` is on</summary>
    [JsonPropertyName("raw")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Raw { get; init; }

    /// <summary>What the writer sent. Only while `llm.captureWrites` is on</summary>
    [JsonPropertyName("prompt")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public List<ScriptPromptMessage>? Prompt { get; init; }
}

public sealed record ScriptRatingInput
{
    [JsonPropertyName("rating")]
